INSERT INTO admin_roles(name,description) VALUES('super_admin','full administrative scope'),('operations_admin','marketplace operations'),('finance_admin','financial operations'),('moderation_admin','moderation and abuse'),('read_only_auditor','read only') ON CONFLICT(name) DO NOTHING;
INSERT INTO admin_permissions(code,description) VALUES
('users.read','read users'),('users.manage','manage users'),('sellers.read','read sellers'),('sellers.manage','manage sellers'),('listings.read','read listings'),('listings.manage','moderate listings'),
('orders.read','read orders'),('orders.manage','manage orders'),('payments.read','read payments'),('escrow.read','read escrow'),('escrow.manage','guarded escrow'),
('wallets.read','read custody metadata'),('withdrawals.read','read withdrawals'),('withdrawals.approve','approve withdrawals'),('payouts.read','read payouts'),('payouts.approve','approve payouts'),
('points.read','read points'),('points.manage','manage points'),('promos.manage','manage promos'),('settings.read','read settings'),('settings.manage','manage settings'),
('audit.read','read audit'),('emergency.manage','emergency controls') ON CONFLICT(code) DO NOTHING;
INSERT INTO admin_role_permissions(role_id,permission_code) SELECT r.id,p.code FROM admin_roles r JOIN admin_permissions p ON p.code IN('users.read','users.manage','sellers.read','sellers.manage','listings.read','listings.manage','orders.read','orders.manage','points.read','points.manage','promos.manage','audit.read') WHERE r.name='operations_admin' ON CONFLICT DO NOTHING;
INSERT INTO admin_role_permissions(role_id,permission_code) SELECT r.id,p.code FROM admin_roles r JOIN admin_permissions p ON p.code IN('sellers.read','payments.read','escrow.read','escrow.manage','wallets.read','withdrawals.read','withdrawals.approve','payouts.read','payouts.approve','audit.read','emergency.manage') WHERE r.name='finance_admin' ON CONFLICT DO NOTHING;
INSERT INTO admin_role_permissions(role_id,permission_code) SELECT r.id,p.code FROM admin_roles r JOIN admin_permissions p ON p.code IN('users.read','sellers.read','sellers.manage','listings.read','listings.manage','orders.read','audit.read') WHERE r.name='moderation_admin' ON CONFLICT DO NOTHING;
INSERT INTO admin_role_permissions(role_id,permission_code) SELECT r.id,p.code FROM admin_roles r JOIN admin_permissions p ON p.code IN('users.read','sellers.read','listings.read','orders.read','payments.read','escrow.read','wallets.read','withdrawals.read','payouts.read','points.read','audit.read','settings.read') WHERE r.name='read_only_auditor' ON CONFLICT DO NOTHING;
INSERT INTO admin_role_permissions(role_id,permission_code) SELECT r.id,p.code FROM admin_roles r CROSS JOIN admin_permissions p WHERE r.name='super_admin' ON CONFLICT DO NOTHING;
INSERT INTO seller_point_levels(level,name,min_points,min_completed_sales,max_dispute_rate_bps,advance_payout_allowed) VALUES(0,'Nuevo',0,0,10000,FALSE),(1,'Establecido',100,5,2500,FALSE),(2,'Confiable',500,20,1000,FALSE),(3,'Avanzado',1500,50,500,TRUE),(4,'Preferente',3000,100,250,TRUE) ON CONFLICT(level) DO NOTHING;
INSERT INTO seller_payout_policies(mode,label,requires_level,buyer_protection_required,admin_approval_required) VALUES('standard_escrow','Liquidación protegida',0,TRUE,FALSE),('early_release','Liquidación anticipada limitada',3,TRUE,TRUE),('advance_payout','Pago anticipado',4,FALSE,TRUE) ON CONFLICT(mode) DO NOTHING;
