CREATE TABLE IF NOT EXISTS admin_roles(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),name TEXT NOT NULL UNIQUE,description TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS admin_role_bindings(account_id UUID NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,role_id UUID NOT NULL REFERENCES admin_roles(id) ON DELETE CASCADE,granted_by UUID REFERENCES accounts(id),granted_at TIMESTAMPTZ NOT NULL DEFAULT now(),revoked_at TIMESTAMPTZ,PRIMARY KEY(account_id,role_id));
CREATE TABLE IF NOT EXISTS admin_permissions(code TEXT PRIMARY KEY,description TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS admin_role_permissions(role_id UUID NOT NULL REFERENCES admin_roles(id) ON DELETE CASCADE,permission_code TEXT NOT NULL REFERENCES admin_permissions(code),PRIMARY KEY(role_id,permission_code));
CREATE TABLE IF NOT EXISTS admin_audit_events(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),actor_account_id UUID REFERENCES accounts(id),action_code TEXT NOT NULL,resource_type TEXT NOT NULL,resource_id UUID,decision TEXT NOT NULL CHECK(decision IN('allowed','denied')),reason TEXT,request_id TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),previous_hash TEXT,current_hash TEXT);
CREATE INDEX IF NOT EXISTS admin_audit_resource_idx ON admin_audit_events(resource_type,resource_id,created_at DESC);
CREATE TABLE IF NOT EXISTS seller_point_levels(level SMALLINT PRIMARY KEY,name TEXT NOT NULL UNIQUE,min_points BIGINT NOT NULL CHECK(min_points>=0),min_completed_sales INTEGER NOT NULL DEFAULT 0 CHECK(min_completed_sales>=0),max_dispute_rate_bps INTEGER NOT NULL DEFAULT 10000 CHECK(max_dispute_rate_bps BETWEEN 0 AND 10000),advance_payout_allowed BOOLEAN NOT NULL DEFAULT FALSE,active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS seller_points_ledger(id BIGSERIAL PRIMARY KEY,seller_account_id UUID NOT NULL REFERENCES sellers(account_id),delta_points INTEGER NOT NULL CHECK(delta_points<>0),reason_code TEXT NOT NULL,reference_id UUID,idempotency_key TEXT NOT NULL UNIQUE,actor UUID REFERENCES accounts(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE OR REPLACE VIEW seller_point_balances AS SELECT seller_account_id,COALESCE(SUM(delta_points),0)::BIGINT points FROM seller_points_ledger GROUP BY seller_account_id;
CREATE TABLE IF NOT EXISTS seller_payout_policies(mode TEXT PRIMARY KEY,label TEXT NOT NULL,requires_level SMALLINT NOT NULL REFERENCES seller_point_levels(level),buyer_protection_required BOOLEAN NOT NULL,admin_approval_required BOOLEAN NOT NULL DEFAULT TRUE,active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS seller_payout_mode_requests(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),seller_account_id UUID NOT NULL REFERENCES sellers(account_id),requested_mode TEXT NOT NULL REFERENCES seller_payout_policies(mode),seller_points_snapshot BIGINT NOT NULL CHECK(seller_points_snapshot>=0),completed_sales_snapshot INTEGER NOT NULL CHECK(completed_sales_snapshot>=0),dispute_rate_bps_snapshot INTEGER NOT NULL CHECK(dispute_rate_bps_snapshot BETWEEN 0 AND 10000),status TEXT NOT NULL DEFAULT 'requested' CHECK(status IN('requested','approved','rejected','suspended','revoked')),reviewed_by UUID REFERENCES accounts(id),review_reason TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),reviewed_at TIMESTAMPTZ);
